def clone_table(
    connection: DatabaseConnection,
    source_table: str,
    target_table: str
) -> None:
    """
    Clone a table's structure and data from source to target.

    Drops target if it exists, then recreates and copies data.
    """

    # Get schema
    schema = get_table_schema(connection, source_table)

    if not schema:
        raise ValueError(f"Could not get schema for {source_table}")

    # Build CREATE TABLE statement
    columns_sql = []

    for col in schema:
        col_sql = f'"{col["name"]}" {col["type"]}'

        if col.get("notnull"):
            col_sql += " NOT NULL"

        if col.get("default_value") is not None:
            col_sql += f" DEFAULT {col['default_value']}"

        columns_sql.append(col_sql)

    # Get primary key info
    if connection.db_type == "sqlite":
        # Check for primary key
        pk_cols = [c["name"] for c in schema if c.get("pk", False)]
        if pk_cols:
            pk_sql = ", ".join(f'"{c}"' for c in pk_cols)
            columns_sql.append(f"PRIMARY KEY ({pk_sql})")

    create_sql = f'CREATE TABLE "{target_table}" ({", ".join(columns_sql)})'

    # Drop if exists
    try:
        update_data(connection, f'DROP TABLE IF EXISTS "{target_table}"')
    except Exception:
        pass

    # Create
    update_data(connection, create_sql)

    # Copy data
    column_names = [c["name"] for c in schema]
    quoted_cols = ", ".join(f'"{c}"' for c in column_names)

    copy_query = f'INSERT INTO "{target_table}" ({quoted_cols}) SELECT {quoted_cols} FROM "{source_table}"'
    update_data(connection, copy_query)


def get_autofix_table_name(staging_table: str) -> str:
    """Generate the autofix staging table name."""

    return f"autofix_{staging_table}"


def run_cross_reference_fixes(
    connection: DatabaseConnection,
    tables_config: dict,
    autofix_tables: dict,
    run_id: str = None,
    changelog_table: str = "change_log"
) -> dict:
    """
    Run cross-reference (SQL join-based) auto-fixes.

    These fixes compare data across tables and fix mismatches.

    Returns:
        {"fix_name": {"fixed": int, "rows_changed": int}}
    """

    from functions.auto_fixes.dirty_ecommerce.cross_reference_fixes import (
        fix_order_country_from_customer,
        fix_order_items_price_from_product,
    )

    results = {}

    # Fix order country from customer (cross-table)
    if "orders" in tables_config:
        orders_autofix = autofix_tables["orders"]

        fix_result = fix_order_country_from_customer(
            connection=connection,
            source_table=tables_config["orders"]["staging_table"],
            target_table=orders_autofix,
            run_id=run_id,
            changelog_table=changelog_table
        )
        results["fix_order_country_from_customer"] = fix_result

    # Fix order item prices from products (cross-table)
    if "order_items" in tables_config:
        items_autofix = autofix_tables["order_items"]

        fix_result = fix_order_items_price_from_product(
            connection=connection,
            source_table=tables_config["order_items"]["staging_table"],
            target_table=items_autofix,
            run_id=run_id,
            changelog_table=changelog_table
        )
        results["fix_order_items_price_from_product"] = fix_result

    return results


def apply_auto_fixes(
    connection: DatabaseConnection,
    staging_table: str,
    autofix_table: str,
    fix_names: list[str],
    run_id: str,
    key_column: str = "id",
    changelog_table: str = "change_log"
) -> dict:
    """
    Apply auto-fixes to the autofix table.

    Logs all changes from staging to autofix staging for reversibility.

    Returns:
        {"fixes_applied": int, "rows_changed": int, "details": list}
    """

    if not fix_names:
        return {"fixes_applied": 0, "rows_changed": 0, "details": []}

    # Get all rows from staging (original) and autofix (to be modified)
    staging_rows = select_data(connection, f'SELECT * FROM "{staging_table}"')
    autofix_rows = select_data(connection, f'SELECT * FROM "{autofix_table}"')

    if len(staging_rows) != len(autofix_rows):
        raise ValueError("Staging and autofix tables have different row counts")

    # Build key lookup for staging
    staging_by_key = {row.get(key_column): row for row in staging_rows}

    total_fixes = 0
    rows_changed = 0
    fix_details = []

    for autofix_row in autofix_rows:
        key_value = autofix_row.get(key_column)
        original_row = staging_by_key.get(key_value)

        if original_row is None:
            continue

        row_changes = {}
        row_fixed = False

        for fix_name in fix_names:
            fix_func = AUTO_FIX_REGISTRY.get(fix_name)

            if not fix_func:
                continue

            try:
                result = fix_func(autofix_row)

                if result.get("fixed", False):
                    total_fixes += 1
                    row_fixed = True

                    # Apply changes
                    if "new_value" in result and "column" not in result:
                        # Single column fix - need to determine column from fix name
                        pass

                    # Handle different result formats
                    if "changes" in result:
                        for col, new_val in result["changes"].items():
                            row_changes[col] = {
                                "old": autofix_row.get(col),
                                "new": new_val
                            }
                            autofix_row[col] = new_val

                    elif "new_value" in result:
                        # Determine column from result or fix function name
                        col = result.get("column") or _infer_column_from_fix(fix_name)
                        if col:
                            row_changes[col] = {
                                "old": autofix_row.get(col),
                                "new": result["new_value"]
                            }
                            autofix_row[col] = result["new_value"]

                    fix_details.append({
                        "fix": fix_name,
                        "row_key": key_value,
                        "reason": result.get("reason", "")
                    })

            except Exception as e:
                fix_details.append({
                    "fix": fix_name,
                    "row_key": key_value,
                    "error": str(e)
                })

        # If row was changed, update in DB and log
        # Filter out changes that would violate NOT NULL constraints
        valid_changes = {}
        for col, change in row_changes.items():
            if change["new"] is None:
                try:
                    schema = get_table_schema(connection, autofix_table)
                    col_info = next((c for c in schema if c["name"] == col), None)
                    if col_info and col_info.get("notnull"):
                        continue
                except Exception:
                    pass
            valid_changes[col] = change

        if not valid_changes:
            continue

        if row_changes:
            rows_changed += 1

            # Build UPDATE query
            set_clauses = []
            params = []

            for col, change in valid_changes.items():
                if connection.db_type == "sqlite":
                    set_clauses.append(f'"{col}" = ?')
                else:
                    set_clauses.append(f'"{col}" = %s')
                params.append(change["new"])

            params.append(key_value)

            if connection.db_type == "sqlite":
                where_clause = f'"{key_column}" = ?'
            else:
                where_clause = f'"{key_column}" = %s'

            update_query = f'UPDATE "{autofix_table}" SET {", ".join(set_clauses)} WHERE {where_clause}'
            try:
                update_data(connection, update_query, tuple(params))
            except Exception:
                continue

            # Log the change
            log_change(
                connection=connection,
                run_id=run_id,
                table_name=changelog_table,
                operation="auto_fix",
                row_key=key_value,
                before_state={k: original_row.get(k) for k in valid_changes},
                after_state={k: autofix_row.get(k) for k in valid_changes},
                reason=f"auto_fix: {', '.join(fix_names)} on {autofix_table}"
            )

    return {
        "fixes_applied": total_fixes,
        "rows_changed": rows_changed,
        "details": fix_details
    }


def _infer_column_from_fix(fix_name: str) -> str | None:
    """Infer which column a fix applies to based on its name."""

    mapping = {
        "fix_invalid_emails": "email",
        "fix_negative_prices": "unit_price",
        "fix_negative_stock": "stock_qty",
        "fix_negative_quantity": "quantity",
        "fix_zero_quantity": "quantity",
        "fix_negative_price": "unit_price",
        "recalculate_line_total": "line_total",
    }

    return mapping.get(fix_name)


def create_autofix_tables(
    connection: DatabaseConnection,
    tables_config: dict
) -> dict:
    """
    Clone all staging tables to autofix staging tables.

    Returns:
        {"table_key": "autofix_table_name"}
    """

    result = {}

    for table_key, table_cfg in tables_config.items():
        staging_table = table_cfg["staging_table"]
        autofix_table = get_autofix_table_name(staging_table)

        clone_table(connection, staging_table, autofix_table)

        result[table_key] = autofix_table

    return result


def drop_autofix_tables(
    connection: DatabaseConnection,
    tables_config: dict
) -> None:
    """Drop all autofix staging tables."""

    for table_key, table_cfg in tables_config.items():
        staging_table = table_cfg["staging_table"]
        autofix_table = get_autofix_table_name(staging_table)

        try:
            update_data(connection, f'DROP TABLE IF EXISTS "{autofix_table}"')
        except Exception:
            pass
